//=============================================================================
// tb_transform_rigorous.v
// Rigorous Self-Checking Testbench for HEVC 1D Transform Core
//
// Automatically generated and validated bit-exactly against HM 18.0:
//   - TLibCommon/TComRom.cpp (g_aiT4, g_aiT8, g_aiT16, g_aiT32)
//   - TLibCommon/TComTrQuant.cpp (fastForwardDst, fastInverseDst, partialButterfly*)
//
// Coverage:
//   - 4-point DST-VII (Forward & Inverse, Pass 1 & Pass 2)
//   - 4-point DCT-II  (Forward & Inverse, Pass 1 & Pass 2)
//   - 8-point DCT-II  (Forward & Inverse, Pass 1 & Pass 2)
//   - 16-point DCT-II (Forward & Inverse, Pass 1 & Pass 2)
//   - 32-point DCT-II (Forward & Inverse, Pass 1 & Pass 2)
//   - Total Vectors: 240 test vectors
//=============================================================================

`timescale 1ns / 1ps
`include "parameter_pkg.vh"

module tb_transform_rigorous;

    reg         clk;
    reg         rst_n;
    reg         fwd_inv_n;
    reg  [2:0]  tu_size_log2;
    reg         is_dst7;
    reg         is_second_pass;

    reg         in_valid;
    wire        in_ready;
    reg  [511:0] in_vec;

    wire        out_valid;
    reg         out_ready;
    wire [511:0] out_vec;

    transform_1d_core uut (
        .clk            (clk),
        .rst_n          (rst_n),
        .fwd_inv_n      (fwd_inv_n),
        .tu_size_log2   (tu_size_log2),
        .is_dst7        (is_dst7),
        .is_second_pass (is_second_pass),
        .in_valid       (in_valid),
        .in_ready       (in_ready),
        .in_vec         (in_vec),
        .out_valid      (out_valid),
        .out_ready      (out_ready),
        .out_vec        (out_vec)
    );

    always #5 clk = ~clk;

    integer total_cnt;
    integer pass_cnt;
    integer err_cnt;

    // Helper task to send 1D vector and check output against golden HM
    task check_vector(
        input [31:0]       test_id,
        input              fwd,
        input [2:0]        size_log2,
        input              dst7,
        input              pass2,
        input [511:0]      in_v,
        input [511:0]      exp_v
    );
        integer k, len;
        reg signed [15:0] act_sample;
        reg signed [15:0] exp_sample;
        reg test_failed;
    begin
        len = (1 << size_log2);
        @(posedge clk);
        #1;
        fwd_inv_n      = fwd;
        tu_size_log2   = size_log2;
        is_dst7        = dst7;
        is_second_pass = pass2;
        in_vec         = in_v;
        in_valid       = 1'b1;

        @(posedge clk);
        #1;
        in_valid       = 1'b0;

        @(posedge clk);
        while (!out_valid) @(posedge clk);
        #1;

        test_failed = 0;
        for (k = 0; k < len; k = k + 1) begin
            act_sample = out_vec[k*16 +: 16];
            exp_sample = exp_v[k*16 +: 16];
            if (act_sample !== exp_sample) begin
                $display("ERROR [Test %0d] Size=%0d Fwd=%b DST7=%b Pass2=%b @ Sample[%0d]: Actual=%0d Expected=%0d (diff=%0d)",
                         test_id, len, fwd, dst7, pass2, k, act_sample, exp_sample, act_sample - exp_sample);
                err_cnt = err_cnt + 1;
                test_failed = 1;
            end
        end
        if (!test_failed) pass_cnt = pass_cnt + 1;
        total_cnt = total_cnt + 1;
    end
    endtask

    initial begin
        clk = 0;
        rst_n = 0;
        fwd_inv_n = 1;
        tu_size_log2 = 2;
        is_dst7 = 0;
        is_second_pass = 0;
        in_valid = 0;
        in_vec = 0;
        out_ready = 1;
        total_cnt = 0;
        pass_cnt = 0;
        err_cnt = 0;

